svg.script:
(function(){
  var f=document.getElementById('f'), base='https://cdn.jsdelivr.net/gh/yuzhe-chen/saxon-arcade@';
  // the newest page version is listed in planner/latest.txt; fall back to a known one
  fetch(base+'main/planner/latest.txt?'+Date.now()).then(function(r){return r.ok?r.text():'';}).catch(function(){return '';})
  .then(function(v){v=(v||'').trim()||'7ad53c85a877a0f2dfa389aa1fd4be9efc562b86';return fetch(base+v+'/planner/index.html');})
  .then(function(r){if(!r.ok)throw new Error(r.status);return r.text();})
  .then(function(h){f.srcdoc=h;})
  .catch(function(){f.srcdoc='<p style="font:18px system-ui;text-align:center;margin-top:40vh">Could not load. Reload the page.</p>';});
})();
